const fs=require("node:fs"),path=require("node:path"),cp=require("node:child_process"),crypto=require("node:crypto");
const scratch=require("./tools/canonical-operation-scratch.js");const root=path.resolve("..");
const owned=scratch.createOwnedTemporaryDirectory({temporaryParent:path.join(root,"artifacts/verification/prospective-metric-checks")});
console.log(JSON.stringify({owned}));
let result;
try{
 const coverage=path.join(owned.rootPath,"coverage");fs.mkdirSync(coverage);
 const env={...process.env,NODE_V8_COVERAGE:coverage,FORCE_COLOR:"0",TINYRUSTLM_QWEN3_NUMERICAL_ORACLE_PYTHON:path.join(root,"artifacts/external/qwen3-numerical-oracle/environment/Scripts/python.exe")};
 result=cp.spawnSync(process.execPath,["--experimental-test-coverage","--test-coverage-include=**/qwen3-numerical-trace-verifier.js","--test","tests/qwen3-numerical-trace-verifier_test.js","tests/qwen3-numerical-differential-profile.test.js"],{cwd:process.cwd(),env,windowsHide:true,encoding:"buffer",timeout:180000,maxBuffer:16*1024*1024});
 for(const name of ["stdout","stderr"]){const p=path.join(root,"artifacts/verification/prospective-metric-final-a1-20260930."+name+".log");const bytes=result[name]||Buffer.alloc(0);fs.writeFileSync(p,bytes,{flag:"wx"});console.log(JSON.stringify({path:p,bytes:bytes.length,sha256:crypto.createHash("sha256").update(bytes).digest("hex")}));}
 console.log(JSON.stringify({exitCode:result.status,signal:result.signal,error:result.error?.message,tail:result.stdout?.toString("utf8").slice(-6500)}));
}finally{scratch.removeOwnedTemporaryDirectory(owned);console.log(JSON.stringify({ownedScratchRemoved:true}));}
